import { Ionicons } from "@expo/vector-icons";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useMemo, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { ReturnProductRows } from "../operations/ReturnProductRows";
import { useCurrentUser } from "../auth/use-current-user";
import { getVendorReturns } from "./vendor.api";

const filters = ["ALL", "REQUESTED", "REVIEWING", "APPROVED", "RECEIVED", "REFUND_PENDING", "CLOSED", "REJECTED"] as const;
const money = (minor: string) => `৳${(Number(minor) / 100).toLocaleString("en-BD")}`;

export function VendorReturnsScreen() {
  const router = useRouter();
  const user = useCurrentUser();
  const [filter, setFilter] = useState<(typeof filters)[number]>("ALL");
  const [search, setSearch] = useState("");
  const query = useQuery({ queryKey: ["vendor", "returns", user?.uid], queryFn: () => getVendorReturns(user!), enabled: Boolean(user) });
  const visible = useMemo(() => (query.data ?? []).filter((item) => filter === "ALL" || item.status === filter).filter((item) => `${item.id} ${item.orderId} ${item.reasonCode} ${item.reasonDetail || ""} ${item.items.map((row) => row.productName).join(" ")}`.toLowerCase().includes(search.trim().toLowerCase())), [filter, query.data, search]);
  const open = query.data?.filter((item) => !["REFUNDED", "REJECTED", "CLOSED"].includes(item.status)).length ?? 0;
  const needsResponse = query.data?.filter((item) => ["REQUESTED", "REVIEWING"].includes(item.status)).length ?? 0;
  const requested = query.data?.reduce((sum, item) => sum + Number(item.requestedAmount.amountMinor), 0) ?? 0;
  const approved = query.data?.reduce((sum, item) => sum + Number(item.approvedAmount?.amountMinor ?? 0), 0) ?? 0;

  if (!user) return <Screen title="Customer returns" description="Sign in with your seller account to view returns." />;
  return <Screen eyebrow="AFTER SALES" title="Customer returns" description="Review claims, respond on time and track inspection, refund and payout impact.">
    <View style={styles.metrics}><Metric icon="return-down-back-outline" label="Total cases" value={String(query.data?.length ?? 0)} /><Metric icon="alert-circle-outline" label="Need attention" value={String(needsResponse)} urgent /><Metric icon="time-outline" label="Open cases" value={String(open)} /><Metric icon="cash-outline" label="Approved impact" value={money(String(approved))} /></View>
    <View style={styles.exposure}><View><Text style={styles.exposureLabel}>TOTAL CUSTOMER REQUESTS</Text><Text style={styles.exposureValue}>{money(String(requested))}</Text></View><View style={styles.exposureDivider} /><View><Text style={styles.exposureLabel}>APPROVED DEDUCTIONS</Text><Text style={styles.exposureValue}>{money(String(approved))}</Text></View><View style={styles.exposureCopy}><Ionicons color={colors.accent} name="shield-checkmark-outline" size={20} /><Text style={styles.muted}>Only approved amounts affect seller settlement.</Text></View></View>
    <View style={styles.toolbar}><View style={styles.search}><Ionicons color={colors.muted} name="search-outline" size={18} /><TextInput accessibilityLabel="Search seller returns" onChangeText={setSearch} placeholder="Search case, order, reason or product" placeholderTextColor={colors.muted} style={styles.searchInput} value={search} />{search ? <Pressable onPress={() => setSearch("")}><Ionicons color={colors.muted} name="close-circle" size={18} /></Pressable> : null}</View><Pressable onPress={() => query.refetch()} style={styles.refresh}><Ionicons color={colors.primary} name="refresh" size={18} /><Text style={styles.refreshText}>Refresh</Text></Pressable></View>
    <View style={styles.filters}>{filters.map((item) => { const active = filter === item; const count = item === "ALL" ? query.data?.length ?? 0 : query.data?.filter((entry) => entry.status === item).length ?? 0; return <Pressable key={item} onPress={() => setFilter(item)} style={[styles.filter, active && styles.filterActive]}><Text style={[styles.filterText, active && styles.filterTextActive]}>{item.replaceAll("_", " ")}</Text><Text style={[styles.filterCount, active && styles.filterCountActive]}>{count}</Text></Pressable>; })}</View>
    {query.isLoading ? <ActivityIndicator color={colors.primary} /> : null}<View style={styles.list}>{visible.map((item) => { const attention = ["REQUESTED", "REVIEWING"].includes(item.status); return <View key={item.id} style={styles.card}><View style={styles.header}><View><Text style={styles.number}>RETURN #{item.id.slice(0, 8).toUpperCase()}</Text><Text style={styles.order}>Order {item.orderId.slice(0, 8).toUpperCase()} · {new Date(item.createdAt).toLocaleDateString("en-BD")}</Text></View><Text style={[styles.status, attention && styles.statusUrgent]}>{item.status.replaceAll("_", " ")}</Text></View><View style={styles.nextStep}><Ionicons color={attention ? colors.warning : colors.accent} name={attention ? "alert-circle-outline" : "git-branch-outline"} size={19} /><View style={styles.flex}><Text style={styles.nextTitle}>{attention ? "Seller review required" : "Return workflow in progress"}</Text><Text style={styles.muted}>{attention ? "Open the case and record the seller response before admin review." : "Follow the recorded case timeline for the next action."}</Text></View></View><Text style={styles.reason}>{item.reasonCode.replaceAll("_", " ")}</Text><Text style={styles.muted}>{item.reasonDetail || "No additional customer note"}</Text><ReturnProductRows items={item.items} /><View style={styles.details}><Cell label="ITEMS" value={String(item.items.reduce((sum, row) => sum + row.quantity, 0))} /><Cell label="REQUESTED" value={money(item.requestedAmount.amountMinor)} /><Cell label="APPROVED" value={item.approvedAmount ? money(item.approvedAmount.amountMinor) : "Pending"} /></View><View style={styles.actions}><Pressable onPress={() => router.push(`/vendor/returns/${item.id}` as never)} style={styles.primary}><Text style={styles.primaryText}>{attention ? "Review and respond" : "Open return case"}</Text><Ionicons color={colors.surface} name="arrow-forward" size={16} /></Pressable></View></View>; })}</View>
    {!query.isLoading && !query.error && !query.data?.length ? <View style={styles.empty}><Ionicons color={colors.success} name="checkmark-circle-outline" size={52} /><Text style={styles.emptyTitle}>No return requests</Text><Text style={styles.muted}>New customer return cases will appear here automatically.</Text></View> : null}{!query.isLoading && !query.error && Boolean(query.data?.length) && !visible.length ? <View style={styles.empty}><Ionicons color={colors.primary} name="search-outline" size={44} /><Text style={styles.emptyTitle}>No matching return cases</Text><Text style={styles.muted}>Try a different search or status filter.</Text></View> : null}{query.error ? <Text style={styles.error}>{query.error.message}</Text> : null}
  </Screen>;
}

function Metric({ icon, label, urgent, value }: { icon: React.ComponentProps<typeof Ionicons>["name"]; label: string; urgent?: boolean; value: string }) { return <View style={styles.metric}><View style={[styles.metricIcon, urgent && styles.metricUrgent]}><Ionicons color={urgent ? colors.warning : colors.primary} name={icon} size={20} /></View><View><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View></View>; }
function Cell({ label, value }: { label: string; value: string }) { return <View style={styles.cell}><Text style={styles.cellLabel}>{label}</Text><Text style={styles.cellValue}>{value}</Text></View>; }

const styles = StyleSheet.create({
  flex: { flex: 1 }, metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, metric: { alignItems: "center", backgroundColor: colors.surface, borderRadius: radius.lg, boxShadow: "0 7px 22px rgba(11,31,58,.06)", flex: 1, flexDirection: "row", gap: spacing.sm, minWidth: 170, padding: spacing.md }, metricIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 42, justifyContent: "center", width: 42 }, metricUrgent: { backgroundColor: "#FFF3D6" }, metricValue: { color: colors.text, fontSize: 20, fontWeight: "700" }, metricLabel: { color: colors.muted, fontSize: 10, marginTop: 2 }, exposure: { alignItems: "center", backgroundColor: colors.navy, borderRadius: radius.lg, flexDirection: "row", flexWrap: "wrap", gap: spacing.lg, padding: spacing.lg }, exposureLabel: { color: "#C9C2B6", fontSize: 8, fontWeight: "700", letterSpacing: .8 }, exposureValue: { color: "#FFFDF8", fontSize: 20, fontWeight: "700", marginTop: 4 }, exposureDivider: { backgroundColor: "rgba(255,255,255,.16)", height: 40, width: 1 }, exposureCopy: { alignItems: "center", backgroundColor: "rgba(255,255,255,.09)", borderRadius: radius.md, flex: 1, flexDirection: "row", gap: 8, minWidth: 220, padding: spacing.sm }, toolbar: { alignItems: "center", flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, search: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, flex: 1, flexDirection: "row", gap: 8, minWidth: 250, paddingHorizontal: 12 }, searchInput: { color: colors.text, flex: 1, minHeight: 45, outlineStyle: "none" } as never, refresh: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", gap: 6, minHeight: 45, paddingHorizontal: spacing.md }, refreshText: { color: colors.primary, fontSize: 10, fontWeight: "700" }, filters: { flexDirection: "row", flexWrap: "wrap", gap: 6 }, filter: { alignItems: "center", borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, flexDirection: "row", gap: 6, paddingHorizontal: 11, paddingVertical: 8 }, filterActive: { backgroundColor: colors.navy, borderColor: colors.navy }, filterText: { color: colors.muted, fontSize: 8, fontWeight: "700" }, filterTextActive: { color: colors.surface }, filterCount: { color: colors.muted, fontSize: 8, fontWeight: "700" }, filterCountActive: { color: "#E8D7A4" }, list: { gap: spacing.md }, card: { backgroundColor: colors.surface, borderRadius: radius.lg, boxShadow: "0 8px 24px rgba(11,31,58,.07)", gap: spacing.sm, padding: spacing.lg }, header: { alignItems: "center", flexDirection: "row", flexWrap: "wrap", gap: spacing.sm, justifyContent: "space-between" }, number: { color: colors.text, fontWeight: "700" }, order: { color: colors.muted, fontSize: 9, marginTop: 3 }, status: { backgroundColor: colors.accentSoft, borderRadius: radius.pill, color: colors.accent, fontSize: 8, fontWeight: "700", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 6 }, statusUrgent: { backgroundColor: "#FFF3D6", color: colors.warning }, nextStep: { alignItems: "center", backgroundColor: colors.background, borderRadius: radius.md, flexDirection: "row", gap: spacing.sm, padding: spacing.sm }, nextTitle: { color: colors.text, fontSize: 11, fontWeight: "700" }, reason: { color: colors.text, fontSize: 16, fontWeight: "700", textTransform: "capitalize" }, muted: { color: colors.muted, fontSize: 10, lineHeight: 17, marginTop: 2 }, details: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, cell: { backgroundColor: colors.background, borderRadius: radius.md, flex: 1, minWidth: 130, padding: spacing.sm }, cellLabel: { color: colors.muted, fontSize: 8, fontWeight: "700" }, cellValue: { color: colors.text, fontWeight: "700", marginTop: 4 }, actions: { alignItems: "flex-end" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, flexDirection: "row", gap: 6, minHeight: 42, paddingHorizontal: spacing.md }, primaryText: { color: colors.surface, fontSize: 10, fontWeight: "700" }, empty: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderStyle: "dashed", borderWidth: 1, gap: spacing.sm, padding: 42 }, emptyTitle: { color: colors.text, fontSize: 19, fontWeight: "700" }, error: { color: colors.danger }
});
